local MS = _G.MS

-- Read-only Edit Mode observation: active layout identity, the Edit Mode
-- session and the VIEWPORT profile migration. Journey never selects, saves,
-- deletes or rewrites a layout: the player changes layouts in Edit Mode.
-- Migration: the "Azeroth Journey" profile generated by previous versions
-- encodes GAME inside a full-span UIParent; under UIParent = GAME it
-- double-compensates. VIEWPORT keeps running and asks the player, once per
-- session, to select their usual layout. LEGACY_MINIMAL never asks.
MS.EditModeWatch = { schemaVersion = 1, state = "UNKNOWN", editing = false, refreshCount = 0 }
local W = MS.EditModeWatch
W.LEGACY_PROFILE_NAME = "Azeroth Journey"

local function Read(object, method, ...)
    if type(object) ~= "table" or type(object[method]) ~= "function" then return end
    local ok, a, b = pcall(object[method], object, ...)
    if ok then return a, b end
end

function W:IsEditModeShown()
    local manager = _G.EditModeManagerFrame
    return self.editing == true or (manager ~= nil and (manager.editModeActive == true or Read(manager, "IsShown") == true))
end

-- Active layout identity from Blizzard's own read API.
function W:ActiveLayout()
    local info = Read(_G.EditModeManagerFrame, "GetActiveLayoutInfo")
    if type(info) ~= "table" or type(info.layoutName) ~= "string" then return nil end
    local types = _G.Enum and _G.Enum.EditModeLayoutType
    local preset = types and types.Preset
    return { name = info.layoutName, layoutType = info.layoutType, custom = preset == nil or info.layoutType ~= preset }
end

-- The generated profile's recorded name, or its default name.
function W:JourneyProfileName()
    local db = rawget(_G, "MultiScreenForeverDB")
    local profiles = type(db) == "table" and db.editModeProfiles
    local seed = type(profiles) == "table" and profiles.seed
    local hint = type(seed) == "table" and seed.identityHint
    local name = type(hint) == "table" and hint.name
    return type(name) == "string" and name ~= "" and name or self.LEGACY_PROFILE_NAME
end

-- Persisted migration progress (additive, versioned; ignored by older builds).
local function Migration(create)
    local db = rawget(_G, "MultiScreenForeverDB")
    local root = type(db) == "table" and db.uiParentViewport
    local stored = type(root) == "table" and root.migration
    if type(stored) == "table" and stored.schemaVersion == W.schemaVersion then return stored end
    if not create or not MS.UIParentMode then return nil end
    local store = MS.UIParentMode:Store()
    store.migration = { schemaVersion = W.schemaVersion }
    return store.migration
end

function W:Refresh(signal)
    self.refreshCount, self.lastSignal = self.refreshCount + 1, signal
    local active = self:ActiveLayout()
    self.active = active
    if not active then self.state = "UNKNOWN"; return self.state end
    local journey = active.custom and active.name == self:JourneyProfileName()
    self.journeyProfileActive = journey
    local viewport = MS.UIParentMode and MS.UIParentMode:IsViewport()
    if not viewport then self.state = "NOT_APPLICABLE"; return self.state end
    if journey then
        self.state = "NEEDED"
        local stored = Migration(true)
        if stored.state ~= "NEEDED" then stored.state, stored.layoutName = "NEEDED", active.name end
        if not self.notified and not self.editing then
            self.notified = true
            if MS.Diagnostics and MS.L and MS.L.EDIT_LAYOUT_MIGRATION_NOTICE then
                MS.Diagnostics:Print(string.format(MS.L.EDIT_LAYOUT_MIGRATION_NOTICE, active.name))
            end
        end
        return self.state
    end
    local stored = Migration(false)
    if stored and stored.state == "NEEDED" then
        stored.state, stored.completedWith = "COMPLETED", active.name
        stored.completedAt = type(time) == "function" and time() or nil
    end
    self.state = stored and stored.state == "COMPLETED" and "COMPLETED" or "NOT_NEEDED"
    return self.state
end

function W:GetStatus()
    return { state = self.state, active = self.active and self.active.name, journeyProfile = self.journeyProfileActive == true,
        editing = self.editing == true }
end

if type(CreateFrame) == "function" then
    local frame = CreateFrame("Frame")
    frame:RegisterEvent("PLAYER_ENTERING_WORLD")
    pcall(frame.RegisterEvent, frame, "EDIT_MODE_LAYOUTS_UPDATED")
    frame:SetScript("OnEvent", function(_, event)
        if event == "PLAYER_ENTERING_WORLD" and type(C_Timer) == "table" and type(C_Timer.After) == "function" then
            C_Timer.After(0, function() W:Refresh(event) end)
        else
            W:Refresh(event)
        end
    end)
    W.eventFrame = frame
    local registry = _G.EventRegistry
    if registry and type(registry.RegisterCallback) == "function" then
        pcall(registry.RegisterCallback, registry, "EditMode.Enter", function() W.editing = true end, W)
        pcall(registry.RegisterCallback, registry, "EditMode.Exit", function() W.editing = false; W:Refresh("EditMode.Exit") end, W)
    end
end
